mapper.select:
SELECT 
FROM orders
WHERE user_id = #{userId}
  AND request_id = #{requestId}
LIMIT 1

mapper.update:
UPDATE orders
SET status = 1, pay_time = #{payTime}
WHERE id = #{id}
  AND status = 0

UPDATE orders
SET status = 2, close_time = #{closeTime}
WHERE id = #{id}
  AND status = 0

mapper.select:
SELECT 
FROM orders
WHERE status = 0
  AND expire_time < #{now}
ORDER BY expire_time ASC
LIMIT #{limit}
